    }
  ],
  "sourceEvidence": [
    {
      "location": "PASSAGE",
      "quote": "따라서 법인의 자산이 개인의 출자에 의해 형성되었더라도 자산의 소유권은 특정 개인이 아닌 법인에게 귀속된다.",
      "mediaId": null,
      "visualObservation": null
    },
